// ── Kente pattern ─────────────────────────────────────────────────────────────
function KentePattern() {
  return (
    <Box component="svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"
      sx={{ position: 'absolute', inset: 0, width: '100%', height: '100%', opacity: 0.045, pointerEvents: 'none' }}
    >
      <defs>
        <pattern id="kente-p" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
          <polygon points="20,2 38,20 20,38 2,20" fill="none" stroke="#f59e0b" strokeWidth="1.2" />
          <polygon points="20,9 31,20 20,31 9,20" fill="none" stroke="#0ea5e9" strokeWidth="0.7" />
          <line x1="0" y1="20" x2="40" y2="20" stroke="#8b5cf6" strokeWidth="0.4" />
          <line x1="20" y1="0" x2="20" y2="40" stroke="#8b5cf6" strokeWidth="0.4" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#kente-p)" />
    </Box>
  );
}

// ── Pricing card ──────────────────────────────────────────────────────────────
function PricingCard({ plan, isAnnual, index }) {
  const navigate = useNavigate();
  const price = isAnnual ? plan.annual : plan.monthly;

  return (
    <Box sx={{
      position: 'relative',
      background: plan.popular
        ? 'rgba(139,92,246,0.08)'
        : 'rgba(255,255,255,0.03)',
      border: plan.popular
        ? '1.5px solid rgba(139,92,246,0.5)'
        : '1px solid rgba(255,255,255,0.07)',
      borderRadius: '24px',
      p: { xs: 3.5, md: 4 },
      height: '100%',
      display: 'flex',
      flexDirection: 'column',
      transition: 'all 0.3s ease',
      animation: `${slideUp} 0.6s ease ${index * 0.1 + 0.2}s both`,
      boxShadow: plan.popular ? '0 0 0 1px rgba(139,92,246,0.2), 0 24px 60px rgba(139,92,246,0.2)' : 'none',
      '&:hover': {
        transform: 'translateY(-6px)',
        boxShadow: plan.popular
          ? '0 0 0 1px rgba(139,92,246,0.4), 0 32px 80px rgba(139,92,246,0.3)'
          : '0 24px 60px rgba(14,165,233,0.12)',
        borderColor: plan.popular ? 'rgba(139,92,246,0.7)' : 'rgba(14,165,233,0.25)',
      },
    }}>
      {plan.popular && (
        <Chip label="Most Popular" size="small" sx={{
          position: 'absolute', top: -14, left: '50%', transform: 'translateX(-50%)',
          background: G, color: '#fff', fontWeight: 700, fontSize: '0.78rem',
          borderRadius: '50px', boxShadow: '0 4px 16px rgba(139,92,246,0.4)',
          '& .MuiChip-label': { px: 2 },
        }} />
      )}

      <Box sx={{ mb: 3 }}>
        <Typography sx={{ color: plan.popular ? '#a78bfa' : '#0ea5e9', fontWeight: 700, fontSize: '0.82rem', textTransform: 'uppercase', letterSpacing: '0.1em', mb: 1 }}>
          {plan.title}
        </Typography>
        <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1, mb: 1 }}>
          <Typography sx={{ color: '#f8fafc', fontWeight: 800, fontSize: '3.2rem', lineHeight: 1, letterSpacing: '-0.03em' }}>
            {price}
          </Typography>
          {plan.monthlyRaw > 0 && (
            <Typography sx={{ color: '#64748b', fontSize: '0.9rem' }}>/mo</Typography>
          )}
        </Box>
        {isAnnual && plan.monthlyRaw > 0 && (
          <Chip label={`Save ${Math.round((1 - plan.annualRaw / plan.monthlyRaw) * 100)}%`} size="small" sx={{
            background: 'rgba(16,185,129,0.12)', color: '#10b981', border: '1px solid rgba(16,185,129,0.25)',
            fontWeight: 700, fontSize: '0.72rem', borderRadius: '50px',
          }} />
        )}
        <Typography sx={{ color: '#64748b', fontSize: '0.9rem', mt: 1.5, lineHeight: 1.6 }}>{plan.description}</Typography>
      </Box>

      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 1.5, mb: 3.5 }}>
        {plan.features.map(({ label, included }) => (
          <Box key={label} sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
            {included
              ? <CheckCircle sx={{ fontSize: 16, color: plan.popular ? '#a78bfa' : '#0ea5e9', flexShrink: 0 }} />
              : <Close sx={{ fontSize: 16, color: '#374151', flexShrink: 0 }} />
            }
            <Typography sx={{ color: included ? '#cbd5e1' : '#374151', fontSize: '0.9rem', fontWeight: included ? 500 : 400 }}>
              {label}
            </Typography>
          </Box>
        ))}
      </Box>

      <Button
        fullWidth
        onClick={() => navigate(plan.ctaPath)}
        variant={plan.popular ? 'contained' : 'outlined'}
        endIcon={<ArrowForward />}
        sx={{
          py: 1.5, borderRadius: '50px', fontWeight: 700, fontSize: '0.95rem',
          ...(plan.popular
            ? { background: G, color: '#fff', boxShadow: '0 6px 24px rgba(139,92,246,0.35)', '&:hover': { background: 'linear-gradient(135deg,#0284c7,#7c3aed)', boxShadow: '0 8px 32px rgba(139,92,246,0.5)', transform: 'translateY(-1px)' } }
            : { borderColor: 'rgba(255,255,255,0.12)', color: 'rgba(255,255,255,0.8)', '&:hover': { borderColor: '#0ea5e9', color: '#38bdf8', background: 'rgba(14,165,233,0.06)' } }
          ),
        }}
      >
        {plan.cta}
      </Button>
    </Box>
  );
}

// ── Main export ───────────────────────────────────────────────────────────────
