import React, { useState, createContext, useContext } from "react";
import {
  Box, Typography, Button, CircularProgress, Alert, Chip, Divider,
} from '@mui/material';
import { keyframes } from '@mui/material/styles';
import {
  Google as GoogleIcon, GraphicEq,
  Translate, Mic, RecordVoiceOver, Security, CheckCircle,
} from '@mui/icons-material';
import { getAuth, signInWithPopup, GoogleAuthProvider } from "firebase/auth";
import { useAuth } from './AuthContext';
import { useNavigate } from 'react-router-dom';
import { auth } from './firebaseConfig';

// ── Animations ─────────────────────────────────────────────────────────────
const slideUp = keyframes`
  from { opacity: 0; transform: translateY(24px); }
  to   { opacity: 1; transform: translateY(0); }
`;
const pulseGlow = keyframes`
  0%,100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 0.85; transform: scale(1.08); }
`;
const waveBar = keyframes`
  0%,100% { transform: scaleY(0.35); }
  50%      { transform: scaleY(1); }
`;
const rotate = keyframes`
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
`;

const G = 'linear-gradient(135deg, #0ea5e9, #8b5cf6)';
const GOLD = '#f59e0b';

// ── Context (kept for downstream consumers) ─────────────────────────────────
export const UserContext = createContext();
export const useUser = () => useContext(UserContext);

// ── Kente pattern ───────────────────────────────────────────────────────────
function KentePattern() {
  return (
    <Box component="svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"
      sx={{ position: 'absolute', inset: 0, width: '100%', height: '100%', opacity: 0.06, pointerEvents: 'none' }}
    >
      <defs>
        <pattern id="kente-w" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
          <polygon points="20,2 38,20 20,38 2,20" fill="none" stroke="#f59e0b" strokeWidth="1.2" />
          <polygon points="20,9 31,20 20,31 9,20" fill="none" stroke="#0ea5e9" strokeWidth="0.7" />
          <line x1="0" y1="20" x2="40" y2="20" stroke="#8b5cf6" strokeWidth="0.4" />
          <line x1="20" y1="0" x2="20" y2="40" stroke="#8b5cf6" strokeWidth="0.4" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#kente-w)" />
    </Box>
  );
}

// ── Waveform ────────────────────────────────────────────────────────────────
function Waveform() {
  const bars = [0.45, 0.7, 1, 0.6, 0.9, 0.55, 0.8, 1, 0.5, 0.72, 0.95, 0.6];
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: '3px', height: 36 }}>
      {bars.map((h, i) => (
        <Box key={i} sx={{
          width: 4, borderRadius: 2, height: `${h * 32}px`,
          background: G,
          animation: `${waveBar} ${0.75 + i * 0.08}s ease-in-out infinite`,
          animationDelay: `${i * 0.06}s`,
        }} />
      ))}
    </Box>
  );
}

// ── Feature row on left panel ───────────────────────────────────────────────
const FEATURES = [
  { icon: <Translate sx={{ fontSize: 22 }} />, text: 'Real-time translation in 50+ languages', color: '#0ea5e9' },
  { icon: <Mic sx={{ fontSize: 22 }} />, text: 'Native African speech recognition & ASR', color: '#8b5cf6' },
  { icon: <RecordVoiceOver sx={{ fontSize: 22 }} />, text: 'Natural text-to-speech synthesis', color: GOLD },
];

const LANGS = ['🇺🇬 Luganda', '🇰🇪 Swahili', '🇳🇬 Yoruba', '🇪🇹 Amharic', '🇿🇦 Zulu', '🇷🇼 Kinyarwanda'];

// ── Main component ──────────────────────────────────────────────────────────
const Welcome = () => {
  const navigate = useNavigate();
  const { setIsAuthenticated } = useAuth();
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleGoogleSignIn = async () => {
    setIsLoading(true);
    setError('');
    const provider = new GoogleAuthProvider();
    try {
      const result = await signInWithPopup(auth, provider);
      const u = result.user;
      localStorage.setItem('user', JSON.stringify({ username: u.displayName, userId: u.uid }));
      localStorage.setItem('loginAt', Date.now().toString());
      setIsAuthenticated(true);
      navigate('/dashboard');
    } catch {
      setError('Sign-in failed. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <Box sx={{ minHeight: '100vh', display: 'flex', background: '#07071a', overflow: 'hidden' }}>
      {/* ── LEFT PANEL ───────────────────────────────── */}
      <Box sx={{
        display: { xs: 'none', md: 'flex' }, flexDirection: 'column',
        width: '55%', position: 'relative', p: 8,
        background: 'linear-gradient(160deg, #07071a 0%, #0f0f2d 60%, #140a2e 100%)',
        borderRight: '1px solid rgba(255,255,255,0.05)',
      }}>
        <KentePattern />
        {/* ambient glow */}
        <Box sx={{ position: 'absolute', top: '20%', left: '10%', width: 400, height: 400, borderRadius: '50%', background: 'radial-gradient(circle, rgba(14,165,233,0.12) 0%, transparent 70%)', animation: `${pulseGlow} 7s ease-in-out infinite`, pointerEvents: 'none' }} />
        <Box sx={{ position: 'absolute', bottom: '15%', right: '5%', width: 300, height: 300, borderRadius: '50%', background: 'radial-gradient(circle, rgba(139,92,246,0.12) 0%, transparent 70%)', animation: `${pulseGlow} 9s ease-in-out infinite 3s`, pointerEvents: 'none' }} />

        <Box sx={{ position: 'relative', zIndex: 1, flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
          {/* Logo */}
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 6, animation: `${slideUp} 0.5s ease both` }}>
            <Box sx={{ width: 44, height: 44, borderRadius: '12px', background: G, display: 'flex', alignItems: 'center', justifyContent: 'center', boxShadow: '0 4px 16px rgba(14,165,233,0.4)' }}>
              <GraphicEq sx={{ color: '#fff', fontSize: 24 }} />
            </Box>
            <Box sx={{ fontWeight: 800, fontSize: '1.4rem', letterSpacing: '-0.02em', background: G, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>
              A·VOICES
            </Box>
          </Box>

          {/* Headline */}
          <Box sx={{ animation: `${slideUp} 0.6s ease 0.1s both` }}>
            <Typography sx={{ color: GOLD, fontWeight: 700, fontSize: '0.82rem', textTransform: 'uppercase', letterSpacing: '0.12em', mb: 2 }}>
              🌍 Africa's Leading Voice AI
            </Typography>
            <Typography sx={{
              color: '#f8fafc', fontWeight: 800, fontSize: '3rem', lineHeight: 1.1,
              letterSpacing: '-0.03em', mb: 1,
            }}>
              Break every
            </Typography>
            <Typography sx={{
              fontWeight: 800, fontSize: '3rem', lineHeight: 1.1, letterSpacing: '-0.03em',
              background: G, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text',
              mb: 3,
            }}>
              language barrier.
            </Typography>
            <Typography sx={{ color: '#64748b', fontSize: '1.05rem', lineHeight: 1.75, maxWidth: 420, mb: 5 }}>
              Transcribe, translate, synthesize and converse with AI — in African and global languages, at enterprise scale.
            </Typography>
          </Box>

          {/* Features */}
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mb: 5, animation: `${slideUp} 0.6s ease 0.2s both` }}>
            {FEATURES.map(({ icon, text, color }) => (
              <Box key={text} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Box sx={{ width: 40, height: 40, borderRadius: '10px', background: `${color}18`, border: `1px solid ${color}30`, display: 'flex', alignItems: 'center', justifyContent: 'center', color, flexShrink: 0 }}>
                  {icon}
                </Box>
                <Typography sx={{ color: '#cbd5e1', fontSize: '0.95rem', fontWeight: 500 }}>{text}</Typography>
              </Box>
            ))}
          </Box>

          {/* Language chips */}
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 4, animation: `${slideUp} 0.6s ease 0.3s both` }}>
            {LANGS.map(l => (
              <Chip key={l} label={l} size="small" sx={{
                background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)',
                color: 'rgba(255,255,255,0.6)', fontSize: '0.76rem', fontWeight: 600, borderRadius: '50px',
                '& .MuiChip-label': { px: 1.5 },
              }} />
            ))}
          </Box>

          {/* Live waveform */}
          <Box sx={{
            background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.07)',
            borderRadius: '16px', p: 2.5, animation: `${slideUp} 0.6s ease 0.35s both`,
          }}>
            <Typography sx={{ color: '#475569', fontSize: '0.72rem', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.08em', mb: 1.5 }}>
              Live Voice Processing
            </Typography>
            <Waveform />
          </Box>
        </Box>
      </Box>

      {/* ── RIGHT PANEL ──────────────────────────────── */}
      <Box sx={{
        flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center',
        p: { xs: 3, md: 6 }, position: 'relative',
        background: { xs: '#07071a', md: 'transparent' },
      }}>
        {/* Mobile bg */}
        <Box sx={{ display: { md: 'none' }, position: 'absolute', inset: 0, pointerEvents: 'none' }}>
          <KentePattern />
        </Box>

        <Box sx={{
          width: '100%', maxWidth: 420, position: 'relative', zIndex: 1,
          animation: `${slideUp} 0.7s ease 0.15s both`,
        }}>
          {/* Mobile logo */}
          <Box sx={{ display: { md: 'none' }, flexDirection: 'column', alignItems: 'center', mb: 5 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 2 }}>
              <Box sx={{ width: 40, height: 40, borderRadius: '10px', background: G, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <GraphicEq sx={{ color: '#fff', fontSize: 20 }} />
              </Box>
              <Box sx={{ fontWeight: 800, fontSize: '1.3rem', background: G, WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', backgroundClip: 'text' }}>
                A·VOICES
              </Box>
            </Box>
          </Box>

          {/* Card */}
          <Box sx={{
            background: 'rgba(255,255,255,0.04)', backdropFilter: 'blur(24px)',
            border: '1px solid rgba(255,255,255,0.09)', borderRadius: '28px',
            p: { xs: 3.5, md: 5 },
            boxShadow: '0 32px 80px rgba(0,0,0,0.6)',
            position: 'relative', overflow: 'hidden',
          }}>
            {/* top accent */}
            <Box sx={{ position: 'absolute', top: 0, left: '15%', right: '15%', height: '2px', background: `linear-gradient(90deg, transparent, ${GOLD}, transparent)` }} />

            <Typography sx={{ color: '#f8fafc', fontWeight: 800, fontSize: '1.8rem', letterSpacing: '-0.02em', mb: 1 }}>
              Welcome back
            </Typography>
            <Typography sx={{ color: '#64748b', fontSize: '0.95rem', mb: 4 }}>
              Sign in to access your voice AI workspace
            </Typography>

            {error && (
              <Alert severity="error" sx={{ mb: 3, borderRadius: '12px', background: 'rgba(239,68,68,0.1)', color: '#f87171', border: '1px solid rgba(239,68,68,0.2)' }}>
                {error}
              </Alert>
            )}

            {/* Google button */}
            <Button
              fullWidth
              onClick={handleGoogleSignIn}
              disabled={isLoading}
              startIcon={isLoading
                ? <CircularProgress size={18} sx={{ color: '#fff' }} />
                : <GoogleIcon sx={{ fontSize: '1.1rem !important' }} />
              }
              sx={{
                background: G, color: '#fff', fontWeight: 700, fontSize: '1rem',
                py: 1.75, borderRadius: '50px',
                boxShadow: '0 6px 28px rgba(14,165,233,0.4)',
                '&:hover': {
                  background: 'linear-gradient(135deg, #0284c7, #7c3aed)',
                  boxShadow: '0 8px 36px rgba(14,165,233,0.55)',
                  transform: 'translateY(-1px)',
                },
                '&.Mui-disabled': { background: '#1e293b', color: '#475569', boxShadow: 'none' },
                mb: 3,
              }}
            >
              {isLoading ? 'Signing in…' : 'Continue with Google'}
            </Button>

            {/* Trust badges */}
            <Box sx={{ display: 'flex', gap: 1.5, justifyContent: 'center', flexWrap: 'wrap', mb: 3 }}>
              {[
                { icon: <Security sx={{ fontSize: 14 }} />, label: 'Firebase secured' },
                { icon: <CheckCircle sx={{ fontSize: 14 }} />, label: 'No credit card' },
              ].map(({ icon, label }) => (
                <Box key={label} sx={{ display: 'flex', alignItems: 'center', gap: 0.6 }}>
                  <Box sx={{ color: '#10b981' }}>{icon}</Box>
                  <Typography sx={{ color: '#475569', fontSize: '0.78rem', fontWeight: 600 }}>{label}</Typography>
                </Box>
              ))}
            </Box>

            <Divider sx={{ borderColor: 'rgba(255,255,255,0.06)', mb: 3 }} />

            <Typography sx={{ color: '#374151', fontSize: '0.78rem', textAlign: 'center', lineHeight: 1.6 }}>
              By continuing, you agree to our{' '}
              <Box component="a" href="/" sx={{ color: '#0ea5e9', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>Terms</Box>
              {' & '}
              <Box component="a" href="/" sx={{ color: '#0ea5e9', textDecoration: 'none', '&:hover': { textDecoration: 'underline' } }}>Privacy Policy</Box>
            </Typography>
          </Box>

          {/* Stats under card */}
          <Box sx={{ display: 'flex', justifyContent: 'center', gap: 4, mt: 4 }}>
            {[{ v: '50+', l: 'Languages' }, { v: '10k+', l: 'Users' }, { v: '99.5%', l: 'Uptime' }].map(({ v, l }) => (
              <Box key={l} sx={{ textAlign: 'center' }}>
                <Typography sx={{ color: '#f8fafc', fontWeight: 800, fontSize: '1.3rem', lineHeight: 1 }}>{v}</Typography>
                <Typography sx={{ color: '#475569', fontSize: '0.72rem', fontWeight: 600, mt: 0.3 }}>{l}</Typography>
              </Box>
            ))}
          </Box>
        </Box>
      </Box>
    </Box>
  );
};

export default Welcome;
