// ── Animations ─────────────────────────────────────────────────────────────
const floatY = keyframes`
  0%,100% { transform: translateY(0); }
  50% { transform: translateY(-14px); }
`;
const pulseGlow = keyframes`
  0%,100% { opacity: 0.5; transform: scale(1); }
  50% { opacity: 0.9; transform: scale(1.06); }
`;
const slideUp = keyframes`
  from { opacity: 0; transform: translateY(30px); }
  to   { opacity: 1; transform: translateY(0); }
`;
const waveBar = keyframes`
  0%,100% { transform: scaleY(0.4); }
  50%      { transform: scaleY(1); }
`;
const fadeIn = keyframes`
  from { opacity: 0; }
  to   { opacity: 1; }
`;

// ── Kente SVG pattern ──────────────────────────────────────────────────────
function KentePattern() {
  return (
    <Box component="svg" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"
      sx={{ position: 'absolute', inset: 0, width: '100%', height: '100%', opacity: 0.04, pointerEvents: 'none' }}
    >
      <defs>
        <pattern id="kente" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
          <rect width="40" height="40" fill="none" />
          <polygon points="20,2 38,20 20,38 2,20" fill="none" stroke="#f59e0b" strokeWidth="1.2" />
          <polygon points="20,8 32,20 20,32 8,20" fill="none" stroke="#0ea5e9" strokeWidth="0.8" />
          <line x1="0" y1="20" x2="40" y2="20" stroke="#8b5cf6" strokeWidth="0.5" />
          <line x1="20" y1="0" x2="20" y2="40" stroke="#8b5cf6" strokeWidth="0.5" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#kente)" />
    </Box>
  );
}

// ── Waveform bars ──────────────────────────────────────────────────────────
function Waveform() {
  const bars = [0.4, 0.7, 1, 0.6, 0.9, 0.5, 0.8, 1, 0.45, 0.7, 0.95, 0.6, 0.75, 0.5, 0.85];
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: '3px', height: 40 }}>
      {bars.map((h, i) => (
        <Box key={i} sx={{
          width: 4, borderRadius: 2,
          height: `${h * 36}px`,
          background: 'linear-gradient(180deg, #0ea5e9, #8b5cf6)',
          animation: `${waveBar} ${0.8 + i * 0.07}s ease-in-out infinite`,
          animationDelay: `${i * 0.06}s`,
        }} />
      ))}
    </Box>
  );
}

